verify_commands.command:
rtk env PATH="$PWD/.venv/bin:$PATH" python -c 'import ast,io,re,subprocess,sys,tokenize
BASE="0033662b5534531d84e39d4a14bf75c8e768e85e"
OWNERS=(ast.Module,ast.ClassDef,ast.FunctionDef,ast.AsyncFunctionDef)
PAT=re.compile(r"#\s*(?:noqa\b|type:\s*ignore\b|pragma:\s*no cover\b|pyright:|mypy:|ruff:|pylint:|(?:fmt|isort):\s*(?:on|off|skip)\b|nosec\b|coding[:=]|[A-Za-z][\w-]*(?:-ok|-via):)",re.I)
class Strip(ast.NodeTransformer):
 def generic_visit(self,node):
  node=super().generic_visit(node)
  if isinstance(node,OWNERS) and node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str): node.body.pop(0)
  return node
def src(ref,path): return subprocess.check_output(["git","show",f"{ref}:{path}"],text=True)
def norm(text,path):
 tree=Strip().visit(ast.parse(text,filename=path,type_comments=True))
 for node in ast.walk(tree):
  if isinstance(node,ast.TypeIgnore): node.lineno=0
 return ast.dump(tree,annotate_fields=True,include_attributes=False)
def protected(text):
 lines=text.splitlines()
 chosen=[lines[t.start[0]-1] for t in tokenize.generate_tokens(io.StringIO(text).readline) if t.type==tokenize.COMMENT and PAT.search(t.string)]
 return (lines[0] if lines and lines[0].startswith("#!") else ""),chosen
bad_ast=[];bad_protected=[]
for path in sys.argv[1:]:
 before=src(BASE,path);after=src("HEAD",path)
 if norm(before,path)!=norm(after,path): bad_ast.append(path)
 if protected(before)!=protected(after): bad_protected.append(path)
assert not bad_ast,f"non-docstring AST/runtime changes: {bad_ast}"
assert not bad_protected,f"directive/shebang changes: {bad_protected}"' tests/external/live_jira_cloud_mutation/_cloud_mutation_support.py tests/external/live_jira_cloud_mutation/conftest.py tests/external/live_jira_cloud_mutation/test_cloud_coordinator_lifecycle.py
